mapper.insert:
INSERT INTO ticket_team_template (
    code, name, description, icon, status, is_system, sort_order, version,
    created_by, updated_by
) VALUES (
    #{code}, #{name}, #{description}, #{icon}, #{status}, #{system}, #{sortOrder}, #{version},
    #{createdBy}, #{updatedBy}
)

mapper.update:
UPDATE ticket_team_template
SET sort_order = #{sortOrder},
    updated_by = #{updatedBy}
WHERE id = #{id}

mapper.delete:
DELETE FROM ticket_team_template
WHERE id = #{id}
  AND is_system = 0
